// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): contextual help topics (slice H).
// Owned and filled by task BE-Q. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-Q fills it). */
export function registerHelpTopicRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// search (P6; p6-plan §2, §3 seam 21): the global scoped search (through access's ReadScope), its index maintenance, saved views and help topics (slice H).
// Created by T-DG6-BE-A with stub route files; the owning tasks fill them (p6-plan §5.1).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps, ModuleRegistration } from "../platform/index.ts";
import { registerHelpTopicRoutes } from "./help-topics.ts";
import { registerSearchRoutes } from "./routes.ts";
import { registerSavedViewRoutes } from "./saved-views.ts";

/**
 * Wiring hook called by the composition root (server.ts). Every route file of the module registers here (T-DG6-BE-A
 * created them as stubs; p6-plan §5.1). The module reports "scaffold" until a route exists, then "active".
 */
export function registerSearchModule(app: FastifyInstance, deps: ModuleDeps): ModuleRegistration {
  const routes = [
    ...registerSearchRoutes(app, deps), // BE-P
    ...registerSavedViewRoutes(app, deps), // BE-Q
    ...registerHelpTopicRoutes(app, deps), // BE-Q
  ];
  return Object.freeze({
    module: "search",
    status: routes.length > 0 ? "active" : "scaffold",
    deliversIn: "P6",
    routes: Object.freeze(routes),
  });
}
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): global scoped search and reindex administration (slice H).
// Owned and filled by task BE-P. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-P fills it). */
export function registerSearchRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// P6 route-file stub (T-DG6-BE-A; p6-plan §5.1, p6-work-split §E/F.1): saved views: columns, filters and sort (slice H).
// Owned and filled by task BE-Q. Until then it registers nothing; its registration line already exists, so the
// owning task edits only this file (and its own tests, pending list and contract exercises).
import type { FastifyInstance } from "fastify";
import type { ModuleDeps } from "../platform/index.ts";

/** Registers this file's routes and returns them as "METHOD /path" (none until BE-Q fills it). */
export function registerSavedViewRoutes(_app: FastifyInstance, _deps: ModuleDeps): string[] {
  return [];
}
// search module suite (P6; T-DG6-BE-A created the module, p6-plan §3 seam 21). The owning tasks add their behaviour
// tests here and under test/integration/search/. Until then: the module wires every route file through its hook, and
// reports "scaffold" while no route exists (a route-free module promises no behaviour).
import { readdirSync } from "node:fs";
import Fastify from "fastify";
import { describe, expect, it } from "vitest";
import type { ModuleDeps } from "../platform/index.ts";
import { registerSearchModule } from "./index.ts";

describe("search module (P6)", () => {
  it("registers through its hook and reports its registration", async () => {
    const app = Fastify({ logger: false });
    try {
      const registration = registerSearchModule(app, {} as ModuleDeps);
      expect(registration.module).toBe("search");
      expect(registration.deliversIn).toBe("P6");
      expect(registration.status).toBe(registration.routes.length > 0 ? "active" : "scaffold");
    } finally {
      await app.close();
    }
  });

  it("has its route files in place (3 created by T-DG6-BE-A, p6-plan §5.1)", () => {
    const files = readdirSync(new URL(".", import.meta.url)).filter(
      (f) => f.endsWith(".ts") && !f.endsWith(".test.ts"),
    );
    expect(files.length - 1).toBeGreaterThanOrEqual(3);
  });
});
