  /api/v1/search:
    get:
      tags: [search]
      operationId: searchRecords
      summary: "Global search over 12 record types (transformations, initiatives, KPIs, benefits, RAID entries, dependencies, decisions, deliverables, evidence, business cases, lessons, change requests) in English, Arabic and codes. Returns only records the caller may read: each hit passes ReadScope for the read permission of its record's own view, with sensitivity (ADR-0051), at query time. Ranked by relevance; no money or KPI value is indexed. `stale` is true when the index is behind or rebuilding. Rate-limit class `search`. 400 search.query_too_short; 503 search.index_unavailable. ADR-0057 §3; REQ-S15-010, REQ-S10-004."
      parameters:
        - { name: q, in: query, required: true, description: "2-200 characters after trimming (shared free-text rules).", schema: { type: string, minLength: 1, maxLength: 200 } }
        - name: recordType
          in: query
          required: false
          description: Repeatable; any of the given record types (default all 12).
          style: form
          explode: true
          schema: { type: array, maxItems: 12, items: { $ref: "#/components/schemas/SearchRecordType" } }
        - { name: transformationId, in: query, required: false, description: "Only this transformation (a transformation the caller cannot read gives an empty page).", schema: { $ref: "#/components/schemas/Uuid" } }
        - { name: includeArchived, in: query, required: false, schema: { type: boolean, default: false } }
        - $ref: "#/components/parameters/Cursor"
        - $ref: "#/components/parameters/Limit"
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/SearchResultPage" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "429": { $ref: "#/components/responses/RateLimited" }
        "503":
          description: "search.index_unavailable: every requested record type's index failed."
          content:
            application/problem+json:
              schema: { $ref: "#/components/schemas/Problem" }
  /api/v1/admin/search/index:
    get:
      tags: [search]
      operationId: getSearchIndexStatus
      summary: "The search index state per record type: status (idle, reindexing, failed), consumed audit sequence, last incremental run, last full reindex, document count (null = Unknown) and last error code; no record data (operations.read; ADR-0053). A reindex is started with runJobNow for job code search.reindex (job.repair). ADR-0057 §2."
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/SearchIndexStatus" }
        "400": { $ref: "#/components/responses/ValidationError" }
        "401": { $ref: "#/components/responses/Unauthenticated" }
        "403": { $ref: "#/components/responses/Forbidden" }
        "429": { $ref: "#/components/responses/RateLimited" }
  /api/v1/saved-views:
    get:
      tags: [search]
      operationId: listSavedViews
      summary: "The caller's active saved views of one list plus the active views shared in the caller's organization (signed in; AUD reads and applies). A shared view of a transformation the caller cannot read is not listed. Owner's views first, then shared, each by name. ADR-0057 §4; REQ-S15-013."
      parameters:
        - { name: listKey, in: query, required: true, schema: { $ref: "#/components/schemas/SavedViewListKey" } }
        - { name: transformationId, in: query, required: false, description: "Views of this transformation and views for any transformation (transformationId null).", schema: { $ref: "#/components/schemas/Uuid" } }
        - $ref: "#/components/parameters/Cursor"
        - $ref: "#/components/parameters/Limit"
      responses:
        "200":
          description: "OK."
          content:
            application/json:
              schema: { $ref: "#/components/schemas/SavedViewPage" }
