  const dName = `Synthetic ${word} deliverable ${seq}`;
  await retitle(api.db, "deliverable", "title", deliverableId, dName, tlId, b);
  push("deliverable", deliverableId, `/api/v1/deliverables/${deliverableId}`, dName);

